/*
 * Offset, inside lod_choose, of the E8 call that runs lod_select on the primary viewpoint list.
 */
inline constexpr std::uint32_t kPrimaryCallOffset = 0x127;

/*
 * The view's fade factor (float) and its per-frame copy in the view's render context, as view_fade_scale
 * and mesh_fade use them.
 */
inline constexpr std::uint32_t kViewFadeScale = 0xac, kContextFadeScale = 0xbe4;

inline std::uint32_t symbol_index(std::string_view name) noexcept {
  const auto& symbols = model().symbols;
  for (std::uint32_t index = 0; index < symbols.size(); ++index)
    if (symbols[index].name == name)
      return index;
  return std::numeric_limits<std::uint32_t>::max();
}

